"use client";

/**
 * Version stamp: a release end card. The product name types in, then a large
 * version number stamps down with a short shake, and a dated line settles under it.
 *
 * Written by Better Design. Painted from the theme prop, so the name takes the
 * product's ink and the version takes its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "800"], subsets: ["latin"] });

const TYPE_AT = 6;
/** Frames per typed character. */
const TYPE_RATE = 1.6;
/** Frames the stamp takes to fall. It lands at `STAMP_AT + FALL`. */
const STAMP_AT = 40;
const FALL = 7;
const SHAKE_FRAMES = 14;
const LINE_AT = 62;

export interface VersionStampProps {
  /** The name that types in first. */
  product?: string;
  /** The number that stamps down. Write it as you want it shown, e.g. "2.0" or "v4". */
  version?: string;
  /** One line under the number, such as the release date. */
  dateLine?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** A release end card: the name types, the version stamps down, the date settles. */
export function VersionStamp({
  product = "Your product",
  version = "2.0",
  dateLine = "Available today",
  theme: themeOverride,
  font,
}: VersionStampProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const typed = Math.max(0, Math.min(product.length, Math.floor((frame - TYPE_AT) / TYPE_RATE)));
  const typing = typed < product.length;
  const caretOn = typing || Math.floor(frame / 15) % 2 === 0;
  const caretFade = interpolate(frame, [STAMP_AT, STAMP_AT + 8], [1, 0], clamp);

  // The stamp accelerates into the card: an ease-in fall, not an ease-out.
  const fall = easings.in(interpolate(frame, [STAMP_AT, STAMP_AT + FALL], [0, 1], clamp));
  const stampScale = interpolate(fall, [0, 1], [2.6, 1]);
  const landed = frame - (STAMP_AT + FALL);
  const decay = landed >= 0 ? Math.max(0, 1 - landed / SHAKE_FRAMES) ** 2 : 0;
  const shakeX = Math.sin(landed * 2.3) * 14 * decay;
  const shakeY = Math.cos(landed * 3.1) * 8 * decay;
  const ring = easings.out(interpolate(landed, [0, 20], [0, 1], clamp));

  const line = easings.out(interpolate(frame, [LINE_AT, LINE_AT + 20], [0, 1], clamp));

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", transform: `translate(${shakeX}px, ${shakeY}px)` }}>
        <div style={{ position: "relative", fontSize: 64, fontWeight: 600, letterSpacing: "-0.025em", color: theme.foreground, height: 78 }}>
          <span style={{ visibility: "hidden" }}>{product}</span>
          <span style={{ position: "absolute", left: 0, top: 0, whiteSpace: "pre" }}>
            {product.slice(0, typed)}
            <span style={{ display: "inline-block", width: 4, height: 58, marginLeft: 6, verticalAlign: "-6px", borderRadius: 2, background: theme.primary, opacity: caretOn ? caretFade : 0 }} />
          </span>
        </div>

        <div style={{ position: "relative", marginTop: 8, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div
            style={{
              position: "absolute",
              width: 520,
              height: 520,
              borderRadius: "50%",
              border: `3px solid ${theme.primary}`,
              opacity: landed >= 0 ? (1 - ring) * 0.5 : 0,
              transform: `scale(${0.5 + ring * 0.9})`,
            }}
          />
          <div
            style={{
              fontSize: 340,
              fontWeight: 800,
              lineHeight: 1,
              letterSpacing: "-0.055em",
              color: theme.primary,
              fontVariantNumeric: "tabular-nums",
              opacity: interpolate(fall, [0, 0.4], [0, 1], clamp),
              transform: `scale(${stampScale})`,
              textShadow: landed >= 0 ? "none" : `0 30px 60px ${withAlpha(theme.primary, 0.3)}`,
            }}
          >
            {version}
          </div>
        </div>

        <div style={{ marginTop: 28, display: "flex", alignItems: "center", gap: 20, opacity: line, transform: `translateY(${(1 - line) * 16}px)` }}>
          <div style={{ width: 48 * line, height: 2, background: theme.border }} />
          <div style={{ fontSize: 36, fontWeight: 500, color: theme.mutedForeground }}>{dateLine}</div>
          <div style={{ width: 48 * line, height: 2, background: theme.border }} />
        </div>
      </div>
    </AbsoluteFill>
  );
}
